const promptTabId = 2052873162;
const promptSection = await browserjs(promptTabId, () => {
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4'));
  const promptH = headings.find(h => h.innerText.includes('Prompt'));
  if (!promptH) return "No prompt heading found";

  let current = promptH.nextElementSibling;
  let text = [promptH.innerText];
  while (current && !['H1', 'H2', 'H3'].includes(current.tagName)) {
    text.push(current.innerText);
    current = current.nextElementSibling;
  }
  return text.join('\n\n');
});

console.log("Prompt Section Text:\n", promptSection);

