const bionicTabId = 2052873163;
const noteText = "Latent growth models are statistical methods used to estimate change over time across individuals. They help researchers understand trajectories, differences in growth, and predictors of change.";

// Fill textarea
const fillRes = await tool.element_interact({
  tabId: bionicTabId,
  ref: "e222",
  operation: "fill",
  value: noteText
});
console.log("Fill result:", JSON.stringify(fillRes));

// Click Convert button
const clickRes = await tool.element_interact({
  tabId: bionicTabId,
  ref: "e268",
  operation: "click"
});
console.log("Click result:", JSON.stringify(clickRes));

// Wait 2 seconds for converter to produce output
await new Promise(r => setTimeout(r, 2000));

// Check DOM for output
const outputDetails = await browserjs(bionicTabId, () => {
  // Look for output containers, bionic reader results, bold elements, etc.
  const preview = document.querySelector('.bionic-reading-output, #output, [class*="output"], [class*="result"]');
  // Look for any b tags or strong tags that were generated
  const strongTags = Array.from(document.querySelectorAll('strong, b')).map(el => el.innerText);

  // Find all elements containing "Latent"
  const allElements = Array.from(document.querySelectorAll('*'));
  const latentElements = allElements.filter(el => el.children.length === 0 && el.innerText.includes('Latent'));

  return {
    previewText: preview?.innerText,
    previewHtml: preview?.innerHTML,
    strongCount: strongTags.length,
    strongSamples: strongTags.slice(0, 10),
    latentParents: latentElements.map(el => el.parentElement?.outerHTML?.slice(0, 300))
  };
});

console.log("Output details:", JSON.stringify(outputDetails, null, 2));

